 private static readonly string[] Before=["Learning goal: You will practice estimating and measuring lengths and adding and subtracting within 100.\nThis lesson is optional because it is an opportunity for extra practice that not all classes may need. In Activity 1, you learn a new center, Target Measurements. In this center, you practice estimating and measuring length in inches and centimeters.","Key ideas:\n- Determine the unknown number that makes an equation true\n- Estimate and measure objects\n- Measurement units must be equal in size and placed or interpreted without gaps, overlaps, or a shifted starting point.","Example 1: Find the value of each expression mentally. \\(58 + 10\\) \\(58 + 12\\) \\(58 + 13\\) \\(67 + 14\\)\nApproach: “How can you make a ten to find the value of \\(67 + 14\\) ?” (67 needs 3 more to make 10. That 3 can come from the 4 ones in 14.)","Step 1: Identify what the task asks you to find or show.\nStep 2: Represent the important quantities or relationships.\nStep 3: Apply the key idea from the lesson.\nStep 4: Explain how the representation supports the result.\nStep 5: Check that the result matches the question.","Common mistake: jumping to an answer before checking that the representation matches the quantities and relationship in the task.","You will practice estimating and measuring lengths and adding and subtracting within 100. This lesson is optional because it is an opportunity for extra practice that not all classes may need."];
 private static readonly string[] After=["Original IM K–5 2021 Grade2 Unit3 Lesson13, OPTIONAL Center Day2. Number Talk mentally compute58+10=68,58+12=70,58+13=71 and67+14=81; for67+14 move3 of the14 ones to67 and compute70+11=81. Activity1 introduces Target Measurements Stage1 Inches and Centimeters (15 minutes): in REAL pairs, choose a whole-inch target of at most10 inches or a whole-centimeter target of at most30 centimeters; one partner draws a straight line while the other says stop; together measure the ACTUAL drawn length with the matching standard ruler, calculate the absolute difference between target and actual length, and record a score for the partner who said stop. Switch jobs and after EIGHT rounds add scores; LOWER total wins. Activity2 introduces Number Puzzles Stage4 Within100 with Composing (25 minutes): with source digit cards and addition gameboard, fill unknown digits to make true addition or subtraction equations within100 that compose or decompose a ten. Afterwards choose Number Puzzles, Estimate and Measure Stage2 or Target Measurements Stage1 centers. Original gameboard/recording sheets and physical participation are teacher-observed. The independent Edulytics numerical companion uses independently chosen values, not a copy of protected printouts.","Never silently interchange centimeters and inches: choose a target and actual measurement in the SAME unit and compute absolute length gap |actual−target|, always nonnegative. Stage1 targets:1..10 whole inches or1..30 whole centimeters; source specifically says no longer than10in or30cm, and the measured drawn result may differ from its target. When two people alternate, the speaker saying STOP earns the deviation score; after8 authentic rounds lower sum wins. The actual line, straightedge, ruler placement, endpoint and partner cooperation must be checked by a teacher, not inferred from typed values. For Number Puzzles Stage4, place physical digit cards on the original source board and solve missing digits so both sides are truly equal, including a new ten in addition or decomposing a ten in subtraction; 47+25=72 because7+5=12, and63−28=35 because63=50+13. Source teacher preparation lists addressing2.MD.A.1,2.MD.A.3,2.MD.A.4,2.NBT.B.5,2.OA.B.2. Warm-up69? No:58+10=68,58+12=70,58+13=71,67+14=81.","SOURCE Number Talk:58+10=68,58+12=70,58+13=71,67+14=81. SOURCE center instructions: target whole-inch length≤10 inches or whole-centimeter length≤30cm; draw, partner says stop, ruler-check both endpoints, score ABSOLUTE difference, rotate roles, sum deviations after8 rounds. Publisher Stage4 Number Puzzles centers involve actual digit cards and gameboards; exact printed puzzle numbers not given in public archived lesson, so Edulytics does not invent them. FIRST-PARTY examples: target8cm actual10cm gives2cm deviation; target7in actual5in gives2in deviation—these are DIFFERENT scores from distinct rounds and units; 47+25=72 with composed ten;63−28=35 with decomposed ten. FIRST-PARTY exit: target12cm actual15cm gap3cm and54+28=82 (compose a ten).","1. Mentally calculate the four real Number Talk sums and explain making a ten with67+14→70+11=81. 2. For authentic Target Measurements Stage1, use a straightedge, two physically present partners and ruler(s). Select target in ONE supported unit: whole inches up to10 or whole centimeters up to30. 3. Partner A draws and Partner B says STOP at an estimated target length; both align a matching-unit ruler at zero, read measured endpoint and record an actual length. 4. Score Partner B with |actual−target| in the original target unit, not the signed difference and never as a different unit. 5. Alternate drawing and stopping; after8 REAL rounds sum the deviations under the rule in use, lower score wins. Teacher verifies authentic measurements and outcomes. 6. At Number Puzzles Stage4, use original digit cards and gameboards, solve unknown digits to make addition/subtraction equations TRUE; e.g. independent47+25 requires a new ten and63−28 requires borrowing a ten. 7. During Center Choice Time the source offers Number Puzzles, Estimate and Measure or Target Measurements, with teacher observation. 8. Finish independent Edulytics arithmetic/measurement checks without claiming source gameboard or actual center completion.","Using a target12 inches or31cm in Stage1 when source maxima are10in and30cm. Taking 10cm versus8cm and reporting signed−2 instead of deviation2cm, or treating 2cm equal in physical length to2 inches. Assigning the line-drawing partner the score rather than the one who says STOP. Ending after2 rounds rather than8 or treating any single digital calculation as a certified game win. Miscounting58+12 as60 or67+14 as71. Treating Number Puzzles Stage4 as only no-regrouping math, despite its explicit compose/decompose focus. Reconstructing protected gameboard card entries from assumptions instead of the authenticated source. A numeric answer does not attest genuine partner measurement or center attendance.","Optional Center Day2. Four source warm-up sums68,70,71,81; Target Measurements Stage1 partner estimates line segments to targets up to10in OR30cm, actual ruler measurement and nonnegative difference, eight rounds with lowest deviation winner. Number Puzzles Stage4 uses original digit cards for missing numbers within100 including composing and decomposing a ten; authentic play teacher-observed, online first-party calculations separate."];
 public static bool IsTarget(CanonicalLessonContentPackDocument d,CanonicalLessonContentPackLesson l)=>d.PackCode==MathematicsCurriculumPackRegistry.CommonCoreCode&&d.VersionCode=="CCSSM-2010"&&d.ContentVersion=="phase30-common-core-rich-content-v1"&&l.LessonCode==Code;
 private static void Guard(CanonicalLessonContentPackDocument d,CanonicalLessonContentPackLesson l){if(!IsTarget(d,l)||l.SourceUrl!=Url||!string.Equals(l.CanonicalBodySha256,Sha,StringComparison.OrdinalIgnoreCase)||!l.OutcomeCodes.SequenceEqual(new[]{"CCSS:2.MD.A.1","CCSS:2.MD.A.3","CCSS:2.MD.A.4","CCSS:2.NBT.B.5","CCSS:2.OA.B.2"}))throw new InvalidOperationException("G2 U03 L13 source/hash/ordered outcomes drifted");}
 private static bool Match(CanonicalLessonContentPackTranslation t,bool after)=>MatchFields([t.Explanation,t.KeyConceptsAndRules,t.WorkedExamples,t.StepByStepSolutions,t.CommonMistakes,t.QuickSummary],after);
 private static bool Match(CurriculumLessonContentTranslation t,bool after)=>MatchFields([t.Explanation,t.KeyConceptsAndRules,t.WorkedExamples,t.StepByStepSolutions,t.CommonMistakes,t.QuickSummary],after);
 private static bool MatchFields(string[] v,bool after)=>v.SequenceEqual(after?After:Before);
 public static void Apply(CanonicalLessonContentPackDocument d){foreach(var l in d.Lessons){if(!IsTarget(d,l))continue;Guard(d,l);var t=l.Translations.Single(x=>x.CultureCode=="en");if(Match(t,true))continue;if(!Match(t,false))throw new InvalidOperationException("G2 U03 L13 previous rich six fields drifted");t.Explanation=After[0];t.KeyConceptsAndRules=After[1];t.WorkedExamples=After[2];t.StepByStepSolutions=After[3];t.CommonMistakes=After[4];t.QuickSummary=After[5];}}
 public static string GetExpectedContentVersion(CanonicalLessonContentPackDocument d,CanonicalLessonContentPackLesson l,string prior)=>IsTarget(d,l)?Version:prior;
 public static bool CanUpgradeExisting(CanonicalLessonContentPackDocument d,CanonicalLessonContentPackLesson l,string prior)=>IsTarget(d,l)&&prior==CommonCoreRichContentCorrections.CorrectionContentVersion;
 public static void ValidateExistingBodyBeforeUpgrade(CanonicalLessonContentPackDocument d,CanonicalLessonContentPackLesson l,string prior,IReadOnlyCollection<CurriculumLessonContentTranslation> rows){Guard(d,l);if(!CanUpgradeExisting(d,l,prior))throw new InvalidOperationException("G2 U03 L13 previous persisted version unknown");if(rows.Count==0)return;if(rows.Count!=1||rows.Single().CultureCode!="en")throw new InvalidOperationException("G2 U03 L13 persisted translations drifted");var old=rows.Single();var t=l.Translations.Single(x=>x.CultureCode=="en");if(old.Title!=t.Title||!(Match(old,false)||Match(old,true)))throw new InvalidOperationException("G2 U03 L13 previous persisted six fields changed");}
